package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string          // PIC X len=1 = "N"
var WsBal decimal.Decimal     // PIC 9(8)V99 len=10 = 0
var WsYear int64              // PIC 99 len=2 = 0
var WsCount int64             // PIC 99 len=2 = 0
var WsBalEd string            // PIC ZZ,ZZZ,ZZ9.99 len=13

var curRec SchedRec
var schedLines []string
var schedPos int

func parseDigitsToInt64(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	// s should be digits; parse manually to tolerate spaces
	var n int64
	for _, c := range s {
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		}
	}
	return n
}

func parseRecord(line string) SchedRec {
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	}
	if len(line) > 16 {
		line = line[:16]
	}
	var r SchedRec
	r.ScAcct = line[0:4]
	nPrin := parseDigitsToInt64(line[4:11])
	r.ScPrin = decimal.New(nPrin, -2)
	nRate := parseDigitsToInt64(line[11:15])
	r.ScRate = decimal.New(nRate, -2)
	r.ScYears = parseDigitsToInt64(line[15:16])
	return r
}

func fitBal(v decimal.Decimal) decimal.Decimal {
	// keep low-order digits that fit PIC 9(8)V99 (10 unscaled digits)
	unscaled := v.Shift(2).Truncate(0)
	base := decimal.NewFromInt(10000000000) // 10^10
	m := unscaled.Mod(base)
	// Mod keeps sign of dividend; balances non-negative
	return m.Shift(-2)
}

func formatBalEd(v decimal.Decimal) string {
	unscaled := v.Shift(2).Truncate(0)
	total := unscaled.IntPart()
	if total < 0 {
		total = -total
	}
	// drop high-order digits beyond picture (8 int digits + 2 frac = 10 digits)
	// total already fits due to store, but mask again for safety
	if total >= 10000000000 {
		total = total % 10000000000
	}
	if total < 0 {
		total = -total
	}
	intPart := total / 100
	fracPart := total % 100
	var digits [8]int
	tmp := intPart % 100000000
	for i := 7; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}
	firstNZ := 8
	for i := 0; i < 8; i++ {
		if digits[i] != 0 {
			firstNZ = i
			break
		}
	}
	out := make([]byte, 13)
	// pattern ZZ,ZZZ,ZZ9.99
	slotPos := [8]int{0, 1, 3, 4, 5, 7, 8, 9}
	for k := 0; k < 8; k++ {
		p := slotPos[k]
		isNine := (k == 7)
		if !isNine && k < firstNZ {
			out[p] = ' '
		} else {
			out[p] = byte('0' + digits[k])
		}
	}
	// commas
	if firstNZ > 1 {
		out[2] = ' '
	} else {
		out[2] = ','
	}
	if firstNZ > 4 {
		out[6] = ' '
	} else {
		out[6] = ','
	}
	out[10] = '.'
	out[11] = byte('0' + int(fracPart/10))
	out[12] = byte('0' + int(fracPart%10))
	return string(out)
}

func formatPic99(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func openSchedFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()
	schedLines = nil
	schedPos = 0
	sc := bufio.NewScanner(f)
	// allow long lines
	sc.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for sc.Scan() {
		line := sc.Text()
		// strip trailing \r for CRLF
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		schedLines = append(schedLines, line)
	}
	if err := sc.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func closeSchedFile() {
	// nothing to do (already closed), kept for structure
}

func MainPara() {
	openSchedFile()
	ReadPara()
	for !(WsEofFlag == "Y") {
		ProcessPara()
	}
	closeSchedFile()
	fmt.Println("SCHEDULES: "+formatPic99(WsCount))
}

func ReadPara() {
	if schedPos >= len(schedLines) {
		WsEofFlag = "Y"
		return
	}
	line := schedLines[schedPos]
	schedPos++
	curRec = parseRecord(line)
}

func ProcessPara() {
	WsBal = curRec.ScPrin
	// fit (no overflow expected)
	WsBal = fitBal(WsBal)
	WsYear = 1
	for !(WsYear > curRec.ScYears) {
		onePlus := decimal.NewFromInt(1).Add(curRec.ScRate.Shift(-2))
		raw := WsBal.Mul(onePlus)
		r := raw.Round(2)
		WsBal = fitBal(r)
		WsBalEd = formatBalEd(WsBal)
		fmt.Println(curRec.ScAcct+" Y"+formatPic99(WsYear)+" "+WsBalEd)
		WsYear = (WsYear + 1) % 100
	}
	WsBalEd = formatBalEd(WsBal)
	fmt.Println(curRec.ScAcct + " FINAL " + WsBalEd)
	WsCount = (WsCount + 1) % 100
	ReadPara()
}

func main() {
	WsEofFlag = "N"
	WsBal = decimal.NewFromInt(0)
	WsYear = 0
	WsCount = 0
	WsBalEd = ""
	MainPara()
}
